comms.text:
@1 וּמַלִיל יְיָ עִם מֹשֶׁה בְּטּוּרָא דְסִינַי לְמֵימָר:
@2 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעַלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַשְּׁמֵט אַרְעָא שְׁמִטְתָא קֳדָם יְיָ:
@3 שִׁית שְׁנִין תִּזְרַע חַקְלָךְ וְשִׁית שְׁנִין תִכְסַח כַּרְמָךְ וְתִכְנוֹשׁ יָת עֲלַלְתָּהּ:
@4 וּבְשַׁתָּא שְׁבִיעֲתָא נְיַח שְׁמִטְתָא יְהֵי לְאַרְעָא דְתַשְׁמֵט קֳדָם יְיָ חַקְלָךְ לָא תִזְרַע וְכַרְמָךְ לָא תִכְסָח:
@5 יָת כַּתֵּי דַחֲצָדָךְ לָא תֶחֱצַד וְיָת עִנְבֵי שִׁבְקָךְ לָא תִקְטוֹף שְׁנַת שְׁמִטְתָא יְהֵי לְאַרְעָא:
@6 וּתְהֵי שְׁמִטַת אַרְעָא לְכוֹן לְמֵיכַל לָךְ וּלְעַבְדָךְ וּלְאַמְתָךְ וְלַאֲגִירָךְ וּלְתוֹתָבָךְ דְדָיְרִין עִמָךְ:
@7 וְלִבְעִירָךְ וּלְחַיְתָא דִי בְאַרְעָךְ תְּהֵי כָל עֲלַלְתַּהּ לְמֵיכָל:
@8 וְתִמְנֵי לָךְ שְׁבַע שְׁמִיטִין דִשְׁנִין שְׁבַע שְׁנִין שְׁבַע זִמְנִין וִיהוֹן לָךְ יוֹמֵי שְּׁבַע שְׁמִטִין דִשְׁנִין אַרְבְּעִין וְתֵשַׁע שְׁנִין:
@9 וְתַעֲבַר שׁוֹפָר יַבָּבָא בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא בְּיוֹמָא דְכִפּוּרַיָא תַּעַבְרוּן שׁוֹפָרָא בְּכָל אַרְעֲכוֹן:
@10 וּתְקַדְשׁוּן יָת שְׁנַת חַמְשִׁין שְׁנִין וְתַקְרוּן חֵרוּתָא בְּאַרְעָא לְכָל יָתְבָהָא יוֹבֵלָא הִיא תְּהֵי לְכוֹן וּתְתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ וּגְבַר לְזַרְעִיתֵהּ תְּתוּבוּן:
@11 יוֹבֵלָא הִיא שְׁנַת חַמְשִׁין שְׁנִין תְּהֵי לְכוֹן לָא תִזְרְעוּן וְלָא תַחְצְדוּן יַת כַּתָּהָא וְלָא תִקְטְפוּן יַת שִׁבְקָהָא:
@12 אֲרֵי יוֹבֵלָא הִיא קוּדְשָׁא תְּהֵי לְכוֹן מִן חַקְלָא תֵּיכְלוּן יָת עֲלַלְתָּהּ:
@13 בְּשַׁתָּא דְיוֹבֵלָא הָדָא תְּתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ:
@14 וַאֲרֵי תְזַבֵּן זְבִינִין לְחַבְרָךְ אוֹ תִזְבֵּן מִידָא דְחַבְרָךְ לָא תוֹנוּן גְבַר יָת אֲחוֹהִי:
@15 בְּמִנְיַן שְׁנַיָא בָּתַר יוֹבֵלָא תִּזְבֵּן מִן חַבְרָךְ בְּמִנְיַן שְׁנֵי עֲלַלְתָּא יְזַבֶּן לָךְ:
@16 לְפוּם סְגִיאוּת שְׁנַיָא תַּסְגֵי זְבִינוֹהִי וּלְפוּם זְעֵרוּת שְׁנַיָא תַּזְעֵר זְבִינוֹהִי אֲרֵי מִנְיַן עֲלַלְתָּא הוּא מְזַבֵּן לָךְ:
@17 וְלָא תוֹנוּן גְבַר יָת חַבְרֵהּ וְתִדְחַל מֵאֱלָהָךְ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@18 וְתַעְבְּדוּן יָת קְיָמַי וְיָת דִינַי תִּטְּרוּן וְתַעֲבְּדוּן יָתְהוֹן וְתֵיתְבוּן עַל אַרְעָא לְרָחֲצָן:
@19 וְתִתֵּן אַרְעָא אִבַּהּ וְתֵיכְלוּן לְמִשְׂבָּע וְתֵיתְבוּן לְרָחֲצָן עֲלַהּ:
@20 וַאֲרֵי תֵימְרוּן מָא נֵיכוּל בְּשַׁתָּא שְׁבִיעֵתָא הָא לָא נִזְרָע וְלָא נִכְנוֹשׁ יָת עֲלַלְתָּנָא:
@21 וֶאֱפַקֵד יָת בִּרְכְּתִי לְכוֹן בְּשַׁתָּא שְׁתִיתֵתָא וְתַעְבֵּד יָת עֲלַלְתָּא לִתְלַת שְׁנִין:
@22 וְתִזְרְעוּן יָת שַׁתָּא תְמִינֵתָא וְתֵיכְלוּן מִן עֲלַלְתָּא עַתִּיקָא עַד שַׁתָּא תְשִׁיעֵתָא עַד מֵעַל עֲלַלְתַּהּ תֵּיכְלוּן עַתִּיקָא:
@23 וְאַרְעָא לָא תִזְדַבַּן לַחֲלוּטִין אֲרֵי דִילִי אַרְעָא אֲרֵי דַיָרִין וְתוֹתָבִין אַתּוּן קֳדָמַי:
@24 וּבְכֹל אַרְעָא אַחֲסַנְתְּכוֹן פֻּרְקָנָא תִּתְּנוּן לְאַרְעָא:
@25 אֲרֵי יִתְמַסְכַּן אָחוּךְ וִיזַבֵּן מֵאַחֲסַנְתֵּהּ וְיֵיתֵי פָרִיקֵהּ דְקָרִיב לֵהּ וְיִפְרוֹק יָת זְבִינֵי אֲחוּהִי:
@26 וּגְבַר אֲרֵי לָא יְהֵי לֵהּ פָּרִיק וְתַדְבֵּק יְדֵהּ וְיַשְׁכַּח כְּמִסַת פֻּרְקָנֵהּ:
@27 וִיחַשֵׁב יָת שְׁנֵי זְבִינוֹהִי וְיָתֵב יָת מוֹתָרָא לִגְבַר דִי זַבֶּן לֵהּ וִיתוּב לְאַחֲסַנְתֵּהּ:
@28 וְאִם לָא תַשְׁכַּח יְדֵהּ כְּמִסַת אֲתֵב לֵהּ וִיהֵי זְבִינוֹהִי בִּידָא דִזְבַן יָתֵהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִפּוֹק בְּיוֹבֵלָא וִיתוּב לְאַחֲסַנְתֵּהּ:
@29 וּגְבַר אֲרֵי יְזַבֵּן בֵּית מוֹתַב קַרְתָּא מַקְפָא שׁוּר וּתְהֵי פוּרְקָנֵהּ עַד מִשְׁלַם שַׁתָּא דִזְבִינוֹהִי עִדָן בְּעִדָן תְּהֵי פוּרְקָנֵהּ:
@30 וְאִם לָא יִתְפָּרַק עַד מִשְׁלַם לֵהּ שַׁתָּא שְׁלֶמְתָּא וִיקוּם בֵּיתָא דִי בְקַרְתָּא דִי לֵהּ שׁוּרָא לַחֲלוּטִין לְדִי זְבַן יָתֵהּ לְדָרוֹהִי לָא יִפּוֹק בְּיוֹבֵלָא:
@31 וּבָתֵּי פַצְחַיָא דִי לֵית לְהוֹן שׁוּר מַקַף סְחוֹר סְחוֹר עַל חֲקַל אַרְעָא יִתְחַשָׁב פֻּרְקָנָא תְּהֵי לֵהּ וּבְיוֹבֵלָא יִפּוֹק:
@32 וְקִרְוֵי לֵיוָאֵי בָּתֵּי קִרְוֵי אַחֲסַנְתְּהוֹן פּוּרְקַן עָלָם תְּהֵי לְלֵיוָאֵי:
@33 וְדִי יִפְרוֹק מִן לֵיוָאֵי וְיִפּוֹק זְבִין בֵּיתָא וְקַרְתָּא אַחֲסַנְתֵּהּ בְּיוֹבֵלָא אֲרֵי בָתֵּי קִרְוֵי לֵיוָאֵי הִיא אַחְסַנְתְּהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@34 וַחֲקַל רְוַח קִרְוֵיהוֹן לָא יִזְדַבָּן אֲרֵי אַחֲסָנַת עָלָם הוּא לְהוֹן:
@35 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ וּתְמוּט יְדֵהּ עִמָךְ וְתַתְקַף בֵּהּ דַיַר וְתוֹתָב וִיחֵי עִמָךְ:
@36 לָא תִסַב מִנֵהּ חִבּוּלְיָא וְרִבִּיתָא וְתִדְחַל מֵאֱלָהָךְ וִיחֵי אָחוּךְ עִמָךְ:
@37 יָת כַּסְפָּךְ לָא תִתֵּן לֵהּ בְּחִבּוּלְיָא וּבְרִבִּיתָא לָא תִתֵּן מֵיכְלָךְ:
@38 אֲנָא יְיָ אֱלָהֲכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם לְמִתַּן לְכוֹן יָת אַרְעָא דִכְנַעַן לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ:
@39 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ עִמָךְ וְיִזְדַבַּן לָךְ לָא תִפְלַח בֵּהּ פָּלְחַן עַבְדִין:
@40 כַּאֲגִירָא כְתוֹתָבָא יְהֵי עִמָךְ עַד שַׁתָּא דְיוֹבֵלָא יִפְלַח עִמָךְ:
@41 וְיִפּוֹק מֵעִמָךְ הוּא וּבְנוֹהִי עִמֵהּ וִיתוּב לְזַרְעִיתֵהּ וּלְאַחֲסָנַת אֲבָהָתוֹהִי יְתוּב:
@42 אֲרֵי עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם לָא יִזְדַבְּנוּן זְבוּן עַבְדִין:
@43 לָא תִפְלָח בֵּהּ בְּקַשְׁיוּ וְתִדְחַל מֵאֱלָהָךְ:
@44 וְעַבְדָךְ וְאַמְתָךְ דִי יְהוֹן לָךְ מִן עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן מִנְהוֹן תִּקְנוּן עַבְדִין וְאַמְהָן:
@45 וְאַף מִבְּנֵי תוֹתָבַיָא עָרְלַיָא דְדָיְרִין עִמְכוֹן מִנְהוֹן תִּקְנוּן וּמִזַרְעִיתְהוֹן דְעִמְכוֹן דִי אִתְיְלִידוּ בְּאַרְעֲכוֹן וִיהוֹן לְכוֹן לְאַחֲסָנָא:
@46 וְתַחֲסוּן יָתְהוֹן לִבְנֵיכוֹן בַּתְרֵיכוֹן לִירוּתַת אַחֲסָנָא לְעָלָם בְּהוֹן תִּפְלְחוּן וּבְאֲחֵיכוֹן בְּנֵי יִשְׂרָאֵל גְבַר בַּאֲחוּהִי לָא תִפְלַח בֵּהּ בְּקַשְׁיוּ:
@47 וַאֲרֵי תַדְבֵּק יַד עָרֵל וְתוֹתָב עִמָךְ וְיִתְמַסְכַּן אָחוּךְ עִמֵהּ וְיִזְדַבַּן לְעָרֵל תּוֹתָב עִמָךְ אוֹ לְאַרְמַי זַרְעִית גִיוֹרָא:
@48 בָּתַר דְיִזְדַבַּן פֻּרְקָנָא תְּהֵי לֵהּ חַד מֵאֲחוֹהִי יִפְרְקִנֵהּ:
@49 אוֹ אַח אֲבוּהִּי אוֹ בַר אַח אֲבוּהִי יִפְרְקִנֵהּ אוֹ מִקָרִיב בִּשְׂרֵהּ מִזַרְעִיתֵהּ יִפְרְקִנֵהּ אוֹ דְתַדְבֵּק יְדֵהּ וְיִתְפָּרָק:
@50 וִיחַשֵׁב עִם זָבְנֵהּ מִשַׁתָּא דְאִזְדַבַּן לֵהּ עַד שַׁתָּא דְיוֹבֵלָא וִיהֵי כְּסַף זְבִינוֹהִי בְּמִנְיַן שְׁנַיָא כְּיוֹמֵי אֲגִירָא יְהֵי עִמֵהּ:
@51 אִם עוֹד סְגִיוּת בִּשְׁנַיָא לְפוּמְהֵן יָתֵב פֻּרְקָנֵהּ מִכְּסַף זְבִינוֹהִי:
@52 וְאִם זְעֵר יִשְׁתָּאַר בִּשְׁנַיָא עַד שַׁתָּא דְיוֹבֵלָא וִיחַשֶׁב לֵהּ כְּפוּם שְׁנוֹהִי יָתֵב יָת פּוּרְקָנֵהּ:
@53 כַּאֲגִיר שְׁנָא בִּשְׁנָא יְהֵי עִמֵהּ לָא יִפְלַח בֵּהּ בְּקַשְׁיוּ לְעֵינָיךְ:
@54 וְאִם לָא יִתְפָּרַק בְּאִלֵין וְיִפּוֹק בְּשַׁתָּא דְיוֹבֵלָא הוּא וּבְנוֹהִי עִמֵהּ:
@55 אֲרֵי דִילִי בְנֵי יִשְׂרָאֵל עַבְדִין עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@56 לָא תַעְבְּדוּן לְכוֹן טַעֲוָן וְצֶלֶם וְקָמָא לָא תְקִימוּן לְכוֹן וְאֶבֶן סָגְדָא לָא תִתְּנוּן בְּאַרְעֲכוֹן לְמִסְגֻד עֲלַהּ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@57 יָת יוֹמֵי שַׁבַּיָא דִילִי תִטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ: פפפ:

@1 **בהר סיני.** מה ענין שמטה אצל הר סיני, והלא כל המצות נאמרו מסיני, אלא מה שמטה נאמרו כללותיה ופרטותיה ודקדוקיה מסיני, אף כלן נאמרו כללותיהן ודקדוקיהן מסיני, כך שנויה בתורת כהנים. ונראה לי שכך פרושה לפי שלא מצינו שמטת קרקעות שנשנית בערבות מואב במשנה תורה, למדנו שכללותיה ופרטותיה כלן נאמרו מסיני, ובא הכתוב ולמד כאן על כל דבור שנדבר למשה שמסיני היו כלם כללותיהן ודקדוקיהן, וחזרו ונשנו בערבות מואב:
@2 **שבת לה'.** לשם ה', כשם שנאמר בשבת בראשית:
@4 **יהיה לארץ.** לשדות ולכרמים: **לא תזמר.** שקוצצין זמורותיה. ותרגומו לא תכסח, ודומה לו (ישעיה לג יב) קוצים כסוחים, (תהלים פ יז) שרפה באש כסוחה:
@5 **את ספיח קצירך.** אפלו לא זרעתה והיא צמחה מן הזרע שנפל בה בעת הקציר, הוא קרוי ספיח: **לא תקצור.** להיות מחזיק בו כשאר קציר, אלא הפקר יהיה לכל: **נזירך.** שהנזרת והפרשת בני אדם מהם ולא הפקרתם: **לא תבצר.** אותם אינך בוצר, אלא מן המפקר:
@6 **והיתה שבת הארץ** וגו' **.** אף על פי שאסרתים עליך, לא באכילה ולא בהנאה אסרתים, אלא שלא תנהוג בהם כבעל הבית, אלא הכל יהיו שוים בה, אתה ושכירך ותושבך: **שבת הארץ לכם לאכלה.** מן השבות אתה אוכל, ואי אתה אוכל מן השמור: **לך ולעבדך ולאמתך.** לפי שנאמר (שמות כג יא) ואכלו אביוני עמך, יכול יהיו אסורים באכילה לעשירים, תלמוד לומר לך ולעבדך ולאמתך, הרי בעלים ועבדים ושפחות אמורים כאן: **ולשכירך ולתושבך.** אף הגוים:
@7 **ולבהמתך ולחיה.** אם חיה אוכלת בהמה לא כל שכן, שמזונותיה עליך, מה תלמוד לומר ולבהמתך, מקיש בהמה לחיה, כל זמן שחיה אוכלת מן השדה האכל לבהמתך מן הבית, כלה לחיה מן השדה כלה לבהמתך מן הבית:
@8 **שבתת שנים.** שמטות שנים. יכול יעשה שבע שנים רצופות שמטה ויעשה יובל אחריהם, תלמוד לומר שבע שנים שבע פעמים, הוי אומר כל שמטה ושמטה בזמנה: **והיו לך ימי שבע** וגו' **.** מגיד לך שאף על פי שלא עשית שמטות עשה יובל לסוף ארבעים ותשע שנה. ופשוטו של מקרא יעלה לך חשבון שנות השמטות למספר ארבעים ותשע:
@9 **והעברת.** לשון (שמות לו ו) ויעבירו קול במחנה, לשון הכרזה: **ביום הכפורים.** ממשמע שנאמר ביום הכפורים איני יודע שהוא בעשור לחדש, אם כן למה נאמר בעשור לחדש, אלא לומר לך תקיעת עשור לחדש דוחה שבת בכל ארצכם, ואין תקיעת ראש השנה דוחה שבת בכל ארצכם, אלא בבית דין בלבד:
@10 **וקדשתם.** בכניסתה מקדשין אותה בבית דין ואומרים מקדשת השנה: **וקראתם דרור.** לעבדים, בין נרצע, בין שלא כלו לו שש שנים משנמכר. אמר ר' יהודה מהו לשון דרור, כמדייר בי דירא ומסחר בכל מדינה וכו' , שדר בכל מקום שהוא רוצה ואינו ברשות אחרים: **יובל הוא.** שנה זאת מבדלת משאר שנים בנקיבת שם לה לבדה. ומה שמה, יובל שמה, על שם תקיעת שופר: **ושבתם איש אל אחזתו.** שהשדות חוזרות לבעליהן: **ואיש אל משפחתו תשבו.** לרבות את הנרצע:
@11 **יובל הוא שנת החמשים שנה.** מה תלמוד לומר, לפי שנאמר וקדשתם וגו' , כדאיתא בראש השנה (ח ב) ובתורת כהנים: **את נזריה.** את הענבים המשמרים. אבל בוצר אתה מן המפקרים, כשם שנאמר בשביעית כך נאמר ביובל, נמצאו שתי שנים קדושות סמוכות זו לזו, שנת ארבעים ותשע שמטה ושנת החמשים יובל:
@12 **קדש תהיה לכם.** תופסת דמיה כהקדש. יכול תצא היא לחלין, תלמוד לומר תהיה, בהויתה תהא: **מן השדה תאכלו.** על ידי השדה אתה אוכל מן הבית, שאם כלה לחיה מן השדה אתה צריך לבער מן הבית, כשם שנאמר בשביעית כך נאמר ביובל:
@13 **תשבו איש אל אחזתו.** והרי כבר נאמר (פסוק י) ושבתם איש אל אחזתו, אלא לרבות המוכר שדהו ועמד בנו וגאלה שחוזרת לאביו ביובל:
@14 **וכי תמכרו** וגו' **.** לפי פשוטו כמשמעו. ועוד יש דרשה מנין כשאתה מוכר, מכור לישראל חברך, תלמוד לומר וכי תמכרו ממכר לעמיתך מכור, ומנין שאם באת לקנות קנה מישראל חברך, תלמוד לומר או קנה מיד עמיתך: **אל תונו.** זו אונאת ממון:
@15 **במספר שנים אחר היובל תקנה.** זהו פשוטו לישב מקרא על אפניו על האונאה בא להזהיר, כשתמכור או תקנה קרקע דע כמה שנים יש עד היובל. ולפי השנים ותבואות השדה שהיא ראויה לעשות ימכור המוכר ויקנה הקונה, שהרי סופו להחזירה לו בשנת היובל. ואם יש שנים מועטות וזה מוכרה בדמים יקרים הרי נתאנה לוקח, ואם יש שנים מרבות ואכל ממנה תבואות הרבה ולקחה בדמים מועטים הרי נתאנה מוכר, לפיכך צריך לקנותה לפי הזמן. וזהו שנאמר במספר שני תבואות ימכר לך, לפי מנין שני התבואות שתהא עומדת ביד הלוקח תמכור לו. ורבותינו דרשו מכאן, שהמוכר שדהו אינו רשאי לגאול פחות משתי שנים, שתעמוד שתי שנים ביד הלוקח מיום ליום, ואפלו יש שלש תבואות באותן שתי שנים, כגון שמכרה לו בקמותיה. ו''שני'' אינו יוצא מפשוטו, כלומר מספר שנים של תבואות, ולא של שדפון, ומעוט שנים שנים:
@16 **תרבה מקנתו.** תמכרנה ביקר: **תמעיט מקנתו.** תמעיט בדמיה:
@17 **ולא תונו איש את עמיתו.** כאן הזהיר על אונאת דברים, שלא יקניט איש את חברו לא ישיאנו עצה שאינה הוגנת לו לפי דרכו והנאתו של יועץ. ואם תאמר, מי יודע אם נתכונתי לרעה, לכך נאמר ויראת מאלהיך, היודע מחשבות הוא יודע. כל דבר המסור ללב, שאין מכיר אלא מי שהמחשבה בלבו, נאמר בו ויראת מאלהיך:
@18 **וישבתם על הארץ לבטח.** שבעון שמטה ישראל גולים, שנאמר (ויקרא כו לד) אז תרצה הארץ את שבתתיה והרצת את שבתתיה, ושבעים שנה שלגלות בבל, כנגד שבעים שמטות שבטלו, היו:
@19 **ונתנה הארץ** וגו' **וישבתם לבטח עליה.** שלא תדאגו משנת בצורת: **ואכלתם לשבע.** אף בתוך המעים תהא בו ברכה:
@20 **ולא נאסף.** אל הבית: **את תבואתנו.** כגון יין ופרות האילן וספיחין הבאים מאליהם:
@21 **לשלש השנים.** למקצת הששית מניסן ועד ראש השנה, ולשביעית ולשמינית, שיזרעו בשמינית במרחשון ויקצרו בניסן:
@22 **עד השנה התשיעת.** עד חג הסכות של תשיעית, שהיא עת בא תבואתה של שמינית לתוך הבית, שכל ימות הקיץ היו בשדה בגרנות, ובתשרי הוא עת האסיף לבית. ופעמים שהיתה צריכה לעשות לארבע שנים, בששית שלפני השמטה השביעית, שהן בטלין מעבודת קרקע שתי שנים רצופות השביעית והיובל, ומקרא זה נאמר בשאר השמטות כלן:
@23 **והארץ לא תמכר.** לתן לאו על חזרת שדות לבעלים ביובל, שלא יהא הלוקח כובשה: **לצמתת.** לפסיקה, למכירה פסוקה עולמית: **כי לי הארץ.** אל תרע עינך בה שאינה שלך:
@24 **ובכל ארץ אחזתכם.** לרבות בתים ועבד עברי, ודבר זה מפורש בקדושין בפרק ראשון (דף כא א) . ולפי פשוטו סמוך לפרשה שלאחריו, שהמוכר אחזתו רשאי לגאלה לאחר שתי שנים או הוא או קרובו, ואין הלוקח יכול לעכב:
@25 **כי ימוך אחיך ומכר.** מלמד שאין אדם רשאי למכור שדהו אלא מחמת דחק עוני: **מאחזתו.** ולא כלה, למד דרך ארץ שישיר שדה לעצמו: **וגאל את ממכר אחיו.** ואין הלוקח יכול לעכב:
@26 **ואיש כי לא יהיה לו גאל.** וכי יש לך אדם בישראל שאין לו גואלים, אלא גואל שיוכל לגאול ממכרו:
@27 **וחשב את שני ממכרו.** כמה שנים היו עד היובל, כך וכך. ובכמה מכרתיה לך בכך וכך. עתיד היית להחזירה ביובל, נמצאת קונה מספר התבואות כפי חשבון של כל שנה. אכלת אותה שלש שנים או ארבע הוצא את דמיהן מן החשבון וטול את השאר, וזהו והשיב את העדף. בדמי המקח על האכילה שאכלה, ויתנם ללוקח: **לאיש אשר מכר לו.** המוכר הזה שבא לגאלה:
@28 **די השיב לו.** מכאן שאינו גואל לחצאין: **עד שנת היובל.** שלא יכנס לתוך אותה שנה כלום, שהיובל משמט בתחלתו:
@29 **בית מושב עיר חומה.** בית בתוך עיר המקפת חומה מימות יהושע בן נון: **והיתה גאלתו.** לפי שנאמר בשדה שיכול לגאלה משתי שנים ואלך כל זמן שירצה ובתוך שתי שנים הראשונים אינו יכול לגאלה, הצרך לפרש בזה שהוא חלוף, שאם רצה לגאול בשנה ראשונה גואלה, ולאחר מכאן אינו גואלה: **והיתה גאלתו.** של בית: **ימים.** ימי שנה שלמה קרויים ימים, וכן (בראשית כד נה) תשב הנערה אתנו ימים:
@30 **וקם הבית** וגו' **לצמיתת.** יצא מכחו של מוכר ועומד בכחו של קונה: **אשר לא חמה.** לו קרינן, אמרו רבותינו זכרונם לברכה אף על פי שאין לו עכשיו, הואיל והיתה לו קודם לכן. ועיר נקבה היא והצרך לכתוב לה, אלא מתוך שצריך לכתוב לא בפנים, תקנו לו במסרת, זה נופל על זה: **לא יצא ביבל.** אמר רב ספרא אם פגע בו יובל בתוך שנתו לא יצא:
@31 **ובתי החצרים.** כתרגומו פצחין, עירות פתוחות מאין חומה. ויש הרבה בספר יהושע (יהושע יג כח) הערים וחצריהם, (בראשית כה טז) בחצריהם ובטירותם: **על שדה הארץ יחשב.** הרי הן כשדות הנגאלים עד היובל ויוצאין ביובל לבעלים אם לא נגאלו: **גאלה תהיה לו.** מיד אם ירצה. ובזה יפה כחו מכח שדות, שהשדות אין נגאלות עד שתי שנים: **וביבל יצא.** בחנם:
@32 **וערי הלוים.** ארבעים ושמנה עיר שנתנו להם: **גאלת עולם.** גואל מיד אפלו לפני שתי שנים, אם מכרו שדה משדותיהם הנתונות להם באלפים אמה סביבות הערים, או אם מכרו בית בעיר חומה, גואלין לעולם, ואינו חלוט לסוף שנה:
@33 **ואשר יגאל מן הלוים.** ואם יקנה בית או עיר מהם: **ויצא ביבל.** אותו ממכר של בית או של עיר וישוב ללוי שמכרו, ולא יהיה חלוט כשאר בתי ערי חומה של ישראל. וגאלה זו לשון מכירה. דבר אחר לפי שנאמר (פסוק לב) , גאלת עולם תהיה ללוים, יכול לא דבר הכתוב אלא בלוקח ישראל שקנה בית בערי הלוים, אבל לוי שקנה מלוי יהיה חלוט, תלמוד לומר ואשר יגאל מן הלוים, אף [לוי] הגואל מיד לוי גואל גאלת עולם: **ויצא ממכר בית.** הרי זו מצוה אחרת, ואם לא גאלה יוצאה ביובל, ואינו נחלט לסוף שנה כבית של ישראל: **כי בתי ערי הלוים הוא אחזתם.** לא היה להם נחלת שדות וכרמים אלא ערים לשבת ומגרשיהם, לפיכך הם להם במקום שדות, ויש להם גאלה כשדות, כדי שלא תפקע נחלתם מהם:
@34 **ושדה מגרש עריהם לא ימכר.** מכר גזבר, שאם הקדיש בן לוי את שדהו ולא גאלה ומכרה גזבר, אינה יוצאה לכהנים ביובל, כמו שנאמר בישראל (ויק' כז) ואם מכר את השדה לאיש אחר לא יגאל עוד, אבל בן לוי גואל לעולם:
@35 **והחזקת בו.** אל תניחהו שירד ויפול ויהיה קשה להקימו, אלא חזקהו משעת מוטת היד. למה זה דומה, למשאוי שעל החמור, עודהו על החמור אחד תופס בו ומעמידו, נפל לארץ, חמשה אין מעמידין אותו: **גר ותושב.** אף אם הוא גר או תושב, ואיזהו תושב, כל שקבל עליו שלא לעבוד עבודה זרה, ואוכל נבלות:
@36 **נשך ותרבית.** חד שוינהו רבנן, ולעבור עליו בשני לאוין: **ויראת מאלהיך.** לפי שדעתו של אדם נמשכת אחר הרבית וקשה לפרוש המנו ומורה לעצמו התר בשביל מעותיו שהיו בטלות אצלו, הצרך לומר ויראת מאלהיך. או התולה מעותיו בנכרי, כדי להלוותם לישראל ברבית, הרי זה דבר המסור ללבו של אדם ומחשבתו, לכך הצרך לומר ויראת מאלהיך:
@38 **אשר הוצאתי** וגו' **.** והבחנתי בין בכור לשאינו בכור, אף אני יודע ונפרע מן המלוה מעות לישראל ברבית ואומר של נכרי הם. דבר אחר אשר הוצאתי אתכם מארץ מצרים על מנת שתקבלו עליכם מצותי אפלו הן כבדות עליכם: **לתת לכם את ארץ כנען.** בשכר שתקבלו מצותי: **להיות לכם לאלהים.** שכל הדר בארץ ישראל אני לו לאלהים, וכל היוצא ממנה כעובד עבודה זרה:
@39 **עבדת עבד.** עבודה של גנאי, שיהא נכר בה כעבד, שלא יוליך כליו אחריו לבית המרחץ ולא ינעול לו מנעליו:
@40 **כשכיר כתושב.** עבודת קרקע ומלאכת אמנות כשאר שכירים התנהג בו: **עד שנת היבל.** אם פגע בו יובל לפני שש שנים, היובל מוציאו:
@41 **הוא ובניו עמו.** אמר רבי שמעון אם הוא נמכר בניו מי מכרן, אלא מכאן שרבו חיב במזונות בניו: **ואל אחזת אבתיו.** אל כבוד אבותיו, ואין לזלזלו בכך: **אחזת.** חזקת:
@42 **כי עבדי הם.** שטרי קודם: **לא ימכרו ממכרת עבד.** בהכרזה כאן יש עבד למכור, ולא יעמידנו על אבן הלקח:
@43 **לא תרדה בו בפרך.** מלאכה שלא לצורך, כדי לענותו. אל תאמר לו החם לי את הכוס הזה, והוא אינו צריך, עדור תחת הגפן עד שאבא. שמא תאמר אין מכיר בדבר אם לצורך אם לאו, ואומר אני לו שהוא לצורך, הרי הדבר הזה מסור ללב, לכך נאמר ויראת:
@44 **ועבדך ואמתך אשר יהיו לך.** אם תאמר אם כן במה אשתמש. בעבדי איני מושל, באמות איני נוחל, שהרי הזהרתני (דברים כ טז) לא תחיה כל נשמה, אלא מי ישמשני: **מאת הגוים.** הם יהיו לך לעבדים: **אשר סביבתיכם.** ולא שבתוך גבול ארצכם, שהרי בהם אמרתי לא תחיה כל נשמה:
@45 **וגם מבני התושבים.** שבאו מסביבותיכם לשא נשים בארצכם וילדו להם, הבן הולך אחר האב, ואינו בכלל לא תחיה, אלא אתה מתר לקנותו כעבד: **מהם תקנו.** אותם תקנו:
@46 **והתנחלתם אתם לבניכם.** החזיקו בהם לנחלה לצורך בניכם אחריכם. ולא יתכן לפרש הנחילום לבניכם, שאם כן היה לו לכתוב והנחלתם אותם לבניכם. והתנחלתם, כמו והתחזקתם: **איש באחיו.** להביא נשיא בעמיו ומלך במשרתיו שלא לרדות בפרך:
@47 **יד גר ותושב.** גר והוא תושב, כתרגומו ערל תותב, וסופו מוכיח ונמכר לגר תושב: **וכי תשיג יד גר ותושב עמך.** מי גרם לו שיעשיר, דבוקו עמך: **ומך אחיך עמו.** מי גרם לו שימוך, דבוקו עמו, על ידי שלמד ממעשיו: **משפחת גר.** זהו הגוי. כשהוא אומר לעקר זה הנמכר לעבודה זרה עצמה להיות לה שמש, ולא לאלהות, אלא לחטוב עצים ולשאוב מים:
@48 **גאלה תהיה לו.** מיד, אל תניחהו שיטמע: **עד שנת היובל.** שהרי כל עצמו לא קנאו אלא לעבדו עד היובל, שהרי ביובל יצא, כמו שנאמר למטה (פסוק נד) ויצא בשנת היובל. ובגוי שתחת ידך הכתוב מדבר ואף על פי כן לא תבא עליו בעקיפין, מפני חלול השם, אלא כשבא לגאל ידקדק בחשבון לפי המגיע בכל שנה ושנה ינכה לו הגוי מן דמיו, אם היו עשרים שנה משנמכר עד היובל וקנאו בעשרים מנה, נמצא שקנה הגוי עבודת שנה במנה, ואם שהה זה אצלו חמש שנים ובא לגאל, ינכה לו חמשה מנים ויתן לו העבד חמש עשרה מנים, וזהו: **והיה כסף ממכרו במספר שנים' כימי שכיר יהיה עמו.** חשבון המגיע לכל שנה ושנה יחשב כאלו נשכר עמו כל שנה במנה וינכה לו:
@51 **אם עוד רבות בשנים.** עד היובל: **לפיהן.** הכל כמו שפרשתי:
@53 **לא ירדנו בפרך לעיניך.** כלומר ואתה רואה:
@54 **ואם לא יגאל באלה.** באלה הוא נגאל, ואינו נגאל בשש: **הוא ובניו עמו.** הנכרי חיב במזונות בניו כישראל:
@55 **כי לי בני ישראל עבדים.** שטרי קודם: **אני ה' אלהיכם.** כל המשעבדן מלמטה כאלו משעבדן מלמעלה:
@56 **לא תעשו לכם אלילם.** כנגד זה הנמכר לגוי, שלא יאמר הואיל ורבי מגלה עריות אף אני כמותו, הואיל ורבי עובד עבודה זרה אף אני כמותו, הואיל ורבי מחלל שבת אף אני כמותו, לכך נאמרו מקראות הללו. ואף הפרשיות הללו נאמרו על הסדר, בתחלה הזהיר על השביעית, ואם חמד ממון ונחשד על השביעית סופו למכור מטלטליו, לכך סמך לה וכי תמכרו ממכר (ויק' כה יד) , מה כתיב ביה או קנה מיד עמיתך (שם) , דבר הנקנה מיד ליד. לא חזר בו, סוף מוכר אחזתו. לא חזר בו, סוף מוכר את ביתו. לא חזר בו, סוף לוה ברבית. כל אלו האחרונות קשות מן הראשונות. לא חזר בו, סוף מוכר את עצמו. לא חזר בו, לא דיו לישראל אלא אפלו לגוי: **ואבן משכית.** לשון כסוי, כמו (שמות לג כב) ושכתי כפי, שמכסין הקרקע ברצפת אבנים: **להשתחות עליה.** אפלו לשמים, לפי שהשתחואה בפשוט ידים ורגלים היא, ואסרה תורה לעשות כן חוץ מן המקדש:
@57 **אני ה'.** נאמן לשלם שכר:

@1 **בהר סיני וגו'**. צריך לדעת למה הזכיר הר סיני במצוה זו, והגם שרבותינו ז''ל אמרו (תורת כהנים) כי ללמד בא שכל המצות נאמרו כללותיהן ופרטותיהן בסיני, עדיין יש מקום לשאלתינו למה לא לימד זה אלא במצוה זו בדיוק ולא במצוה ראשונה או אחרונה, ואולי כי לצד שהזכיר מתנת הארץ דכתיב **אשר אני נותן** דקדק לומר בהר סיני, לומר כי מחמת הר סיני פירוש מה שקיבלו בו היא שנגמרה המתנה, שעל מנת תורה נתן ה' את הארץ:
@1 **עוד** על פי מאמר הגמרא מסכת עבודה זרה (כ'.) ופסקו רמב''ם בפרק ג' מהלכות זכיה וזה לשונו אסור לתת לעכו''ם מתנת חנם ע''כ ואם כן ישראל קודם שקבלו התורה דינם כעכו''ם ואחר קבלת תורה יכול ליתן להם, לזה אמר **בהר סיני** שבזה יוכל לומר אשר אני נותן לכם, ובזה נתישב גם כן למה הוצרך לומר אשר אני נותן כי פשיטא כי הוא הנותן ואין אחר לטעות בו, ותמצא שבפרשת קדושים (לעיל י''ט כ''ג) אמר כי תבואו אל הארץ ונטעתם וגו' ולא הוצרך לומר בה סימן, אלא שנתכוון למה שכתבנו, ומעתה יתיישב למה בחר ה' ללמד בנין אב זה לכל התורה בפרשה זו ולא בפרשה אחרת:
@2 **דבר וגו' ואמרת וגו'**. טעם הכפל, לצד שיש במצוה זו ענין מניעת עבודת אדמה והפקרת הפירות העולים מהאילנות וצמח האדמה, כנגד מניעת עבודת האדמה והכנת הצלחתו אמר **דבר** לשון קושי, כי הוא דבר שאין רצון אדם חפצה בו לצד היותו מניעת הטוב, וכנגד הפקרת הצומח אמר **ואמרת**, כי הוא דבר שכל אחד ישמח בו שיאמר ידו בכל, גם לצד ההבטחות שצוה בענין (פסוק כ''א) ועשת את התבואה לשלש השנים אמר ואמרת אמירה המסעדת את הלב:
@2 **עוד** ירצה לצד שמצוה זו של שביתת הארץ יש בה ב' דברים, הא' דבר מלך שלטון שעל עבדיו חיוב לקיים כל דבר, והב' הגם שיהיה דבר זה בין אדם לחבירו יתחייב עשותו כפי הדין, כי הנותן מתנה לחברו ומתנה עמו בשעת המתנה תנאו קיים, וכמו כן האדון ב''ה בשעת המתנה מתנה תנאים כאומרו אשר אני נותן ולא אמר אשר נתתי, אשר על כן אמר כנגד דבר מלך שלטון אמר דבר, וכנגד היות הדבר מתחייב מהמשפט אמר ואמרת פירוש בלא טעם גזירת מלך יקבלו המאמר:
@2 **ושבתה הארץ וגו'**. צריך לדעת מה היא כוונת הכתוב במאמר זה, אם על שנת השמיטה הרי הוא אומר בסמוך ובשנה השביעית שבת שבתון:
@2 **אכן** נתכוון ה' לומר סמוך לזכרון הנתינה להם שיור לה' בארץ, והוא אומרו **אני נותן** ולא מתנה חלוטה אלא **ושבתה** וגו' **לה'**, וחזר ופירש שיעור שבת זה, אם חודש, אם שנה, בכמה שנים, ואמר **שש שנים ובשנה השביעית שבת** וגו', ומעתה אם לא היה אומר הכתוב ושבתה וגו' אלא מה שאמר אחר כך ובשנה השביעית לא הייתי יודע ששייר ה' לעצמו שנה זו אלא שנתן מתנה חלוטה לצמיתות ולא כן הוא:
@2 **והצצתי** וראיתי כי אלהים חשבה לטובה בסדר מעשה זה, כי אם היה ה' נותן הארץ על תנאי בהבטל התנאי תתבטל המתנה, ובמה שעשה השיור כשישלחו יד בשיור לא מפני זה תתבטל המתנה אלא עליהם לפרוע כל העולה בשיור, והעד הנאמן מה שאמר הכתוב (לקמן כ''ו ל''ד) אז תרצה הארץ את שבתותיה את אשר לא שבתה וגו', ומעתה אין ביטול למתנת הארץ עד עולם:
@2 **עוד** נראה טעם סמיכות ושבתה לאשר אני נותן, על פי דבריהם שאמרו (ב''מ כ''ג.) הן של תלמיד חכם במקום שבועה, והחכם אשר ממנו תוצאות חכמה הוא ה' אלהים, ולזה כשהוציא מפי עליון אני נותן אמירתו במקום שבועה. או גם כן לצד שמתנת ה' לישראל דין צדקה יש לה ואמירתה כדין נדר (ר''ה ו'.), ולזה תכף ומיד תוך כדי דיבור לאומרו אשר אני נותן אמר ושבתה הארץ וגו', וזולת זה מה שאמר אחר כך ובשנה השביעית וגו' אינו תוך כדי דיבור למאמר הנתינה שהרי הפסיק במאמר שש שנים וגו' ושש שנים וגו':
@3 **שש שנים וגו'**. נתכוון ליתן עשה על הזריעה וגו' ועל הזמירה של שנה שביעית, כי לאו הבא מכלל עשה עשה (פסחים מ''א:), והגם שכתב רמב''ם בהלכות שמיטה (פ''א) כי עשה נשמע מאומרו ושבתה הארץ שבת וגו', אף על פי כן אינו נשמע משם עשה דזריעה ועשה דזמירה, או אולי לחייבו בב' עשין, ועיין בפסוק ואספת:
@3 **ושש שנים תזמור**. כפל לומר ושש שנים ולא הספיק לומר שש שנים תזרע שדך ותזמור כרמך, יתבאר על דרך אומרם ז''ל בפרק ה' דשביעית וז''ל בנות שוח שביעית שלהם שנייה וכו', וכתבו הטעם משום שאנו הולכים בהם אחר חנטה וכיון שחנטו בשביעית דינם כפירות שביעית ואסורים בשנה שניה לשביעית, הרי שבאילנות אנו הולכים אחר חנטה ובדגן ובירקות אנו הולכים בהם אחר לקיטה כמו שאמרו בפרק קמא דראש השנה (י''ג:), ואשר על כן הבדיל ה' ואמר שש שנים של זרעוני שדה בפני עצמן ושש שנים של הכרם בפני עצמן לצד שאין משפטן שוה שזה אנו הולכים בו אחר לקיטה וזה אנו הולכים בו אחר חניטה:
@3 **ואספת וגו'**. צריך לדעת למה הוצרך לומר ואספת, ואולי שנתכוון לדייק **ואספת את תבואתה** ולא ספיחיה העולים בשביעית, והכוונה בזה ליתן עשה על אסיפת ספיחים כי לאו הבא מכלל עשה עשה, או ירצה להבטיח שהגם שזרעו הארץ שש שנים וכפי טבע הארץ כשזורעה שנה אחר שנה לא תתן כחה, וכמאמרם ז''ל (ב''ב כ''ט.) זורע שנה אחת ומובירה שנה אחת וכו', שבזה תתן כחה אבל שנה על שנה ובפרט שש שנים ודאי שתכחש הארץ, ויאמר האומר הנה טוב מאד שתשבות הארץ באופן אחד בסדר שתתן כחה בשנת הזריעה, ואין לדבר זה גבול שתהיה שנה השביעית בדיוק שנת שבתון, לזה אמר **שש שנים** ואף על פי כן **ואספת את תבואתה** בגדר הראוי לה בלא הכחשה משנה לשנה, ואין צורך להוביר אותה בשנה משני השש כי יצו ה' את הברכה בארץ הקדושה, ואולי כי לזה גם כן נתכוון באמרו **דבר ואמרת**, דבר כפשטה, ואמרת כי אדרבה מתנה טובה אני נותן להם שיזרעו השדה וכו' שש שנים זה אחר זה ולא תכחש הארץ מתת כחה בשוה מבלי שיצטרכו להוביר זולת שנה השביעית למצות מלך:
@3 **עוד** יתבאר על דרך מה שאמרו בסנהדרין דף כ''ו וז''ל מכריז ר' ינאי פוקו וזרעו בשביעית משום ארנונא, וכתבו התוספות ואם תאמר משום ארנונא התירו לחרוש בשביעית דאורייתא וי''ל וכו' אי נמי י''ל דפיקוח נפש הוא ששואל ממנו ואין לו וכו' ע''כ, והוא מאמר הכתוב **שש שנים** וגו' **ואספת** וגו' פירוש אימתי אין אני מתיר לך אלא שש ולא שבע ואספת כשאתה זורע לאסוף לעצמך אבל לארנונא לתת למושל זרעו אפילו בשביעית כדברי ר' ינאי:
@6 **והיתה שבת וגו'**. פירוש שלא תאמר שיהיה משפטו כשאר שולחן הגבוה שהכהנים זוכים בו אלא לכם לכולכם יחד כהנים לוים ישראלים וכו', וחזר ופרט לך וגו', ואם תאמר אם כן למה נאמר לכם שלא היה לו לומד אלא הארץ לאכלה לך וגו', ונראה כי חש לומר בדרך זה שהייתי אומר הקודם בפסוק קודם באכילה, כדרך שאמרו (ספרי) ענייך ועניי עירך וגו' ממה שאמר הכתוב (רבדים ט''ו ז') כי יהיה בך אביון וגו', לזה קדם הכתוב וכלל כולם יחד ואמר לכם שאין גדר לאחד יותר מחבירו בפירות שביע ית:
@14 **וכי תמכרו וגו'**. בתורת כהנים אמרו וז''ל מנין שאין אונאה לקרקעות תלמוד לומר או קנה מיד אל תונו המטלטלין יש להם אונאה ואין אונאה לקרקעות ע''כ, ובגמרא (ב''מ נ''ו.) הקשו מפסוק את כל ארצו מידו והעלו כל ידו ידו ממש ושאני התם דליכא למימר הכי ע''כ, קשה ונלמוד משם שכשיאמר ידו אין ידו ממש וי''ל שתיבת ידו משמעותו הוא ידו ממש אלא שגם יכול להיות נשמע גם כן רשותו אבל משמעות ידו הוא יותר קרוב בנשמע, ולזה כשיאמר הכתוב ידו הגם שב' הפירושים צודקים בה אין אני דן בה אלא הדרגה היותר קרובה שהוא ידו, ואם אין כוונת הכתוב לומר ידו ממש עליו שלא לומר תיבה שנוכל לפרש בה הבנה זרה, מה שאין כן במקום שאין לפרש בה אלא פירוש אחד לא יחוש הכתוב לדבר בלשון שיכול לישמע בו הענין. ונשאר לנו לחקור זאת לדבריהם ז''ל שדרשו שאזהרת אל תונו אינה אלא במטלטלין והלא עיקר הכתוב במכר קרקעות נאמר:
@14 **ונראה** כי הגם שרבותינו ז''ל דרשו כן הוא על פי ההלכות שהיה בידם מסיני סמכום בכתובים ועל כל פנים יתיישב הכתוב לפי פשוטו על זה הדרך כי לצד שצוה ה' על הארץ שלא תמכר לצמיתות צוה שלא יאנה המוכר ללוקח שאינו בקי במשפטי התורה כי הארץ תהיה לו ולזרעו עד עולם, ואחר כך יבוא בטענת דבר מלך להחזירה לו, ודבר זה כיוצא באונאה זו יוצדק גם בקרקעות המוכר קרקע על מנת שאין עליה מערערים ויצאו עליה מערערים שהוא ביטול מקח, וכאן אין לך מערערים כהוא עצמו שחוזר לערער על שדהו להחזירו בטענת זכות התורה, לזה צוה ה' ואמר במספר שנים וגו' ימכר לך, אלא במה שאמר הכתוב אל תונו סתם שכלל כל מין אונאה זה אינו אלא במטלטלין כמו שדקדק לומר קנו מיד כדברי רבותינו ז''ל:
@15 **במספר וגו** ' **אחר היובל**. צריך לדעת א' למה אמר אחר היובל ולא אמר עד היובל כי שנים הנקנים הם מזמן הקנייה עד היובל לא מה שעברו משנת היובל עד זמן הקנייה, ב' למה שינה הכתוב לשונו כשהזכיר מספר שנים אמר תקנה ותלה הדבר בלוקח וכשהזכיר מספר תבואות אמר ימכר לך יחס הדבר למוכר, ובמסכת ערכין פרק המוכר (כ''ט:) תנן המוכר שדהו בשעת היובל אינו מותר לגאול פחות מב' שנים שנאמר במספר שני תבואות, היתה שנת שדפון או שביעית אינה עולה מן המנין, ר''א אומר מכרה לו בראש השנה מלאה פירות הרי זה אוכל ג' תבואות ע''כ, ובגמרא אינו גואל לא קתני אלא אינו מותר אלמא קסבר איסורא נמי איכא, ולא מבעיא מוכר דקאי בעשה דכתיב ימכר לך אלא אפילו לוקח נמי קאי בעשה דכתיב תקנה ע''כ, עוד תניא שם וז''ל אכלה שנה אחת לפני היובל משלימין לו שנה אחרת אחר היובל ע''כ, נמצינו אומרים ד' הלכות הא' מצוה לשניהם שלא יהיה המכר פחות מגבול האמור בכתוב, ב' שאם היו ג' תבואות בב' שנים הם ללוקח, הג' אם לא היו תבואות בב' שנים כגון שנת שדפון וכו' אינה עולה לו מן המנין, הד' אם אירע יובל בתוך הב' שנים אינה יוצאה עד שישלימו ב' שנים, ופסק הרמב''ם לד' הלכות אלו בפרק י''א מהלכות שמיטה ויובל:
@15 **ועל** פי זה יתיישבו הדקדוקים על נכון אומרו **במספר שנים אחר היובל** פירוש מספר השנים שאומר הכתוב יתחייבו להיות הגם שישלמו אחר היובל כי אין היובל מפקיעם, ושינה הכתוב לשונו לומר פעם אחד תקנה ופעם אחד ימכר להטיל מצוה על הלוקח ועל המוכר שלא יהיה המכר פחות מהאמור, והזכיר השנים והתבואות לתת זכות השנים וזכות התבואות, ואמר **מספר תבואות** ולא אמר מספר תבואה לאם היו שנים שאין בהם תבואה או מחמת שדפון או שנת שמיטה ויובל אינם עולים לו מהמנין, ויש לדעת טעם נכון בדבר זה למה יאסור ה' ללוקח לבל יחזיר השדה פחות מב' שנים וכו' וכי אסור לו לאדם לתת או למחול ממונו או להפקירו ויהיה זה כאחד מהם, ואולי לצד כי רצונו יתברך הוא לבל ימכור אדם שדהו, וכמו שדרשו ז''ל (תודת כהנים בפסוק כ''ה) כי ימוך אחיך וגו' שאין אדם רשאי למכור שדהו ולהניח המעות וכו', לזה יכוון ה' בצוו ללוקח לבל ישיב הקנין למוכר כדי שבאמצעות הדבר יעמוד בין עיניו החלט החזרה תוך ב' שנים ולפעמים ימנע מחמת זה ולא ימכור:
@15 **עוד** נראה על פי מה שכתב רמב''ם שם בפרק י''א וז''ל המוכר שדהו לששים שנה אינה יוצאה ביובל שאינו חוזר ביובל אלא דבר הנמכר סתם או לצמיתות ע''כ, והכסף משנה לא רשם מנין הוציא הרב דין זה, ואולי כי דין זה הוא מה שרשם ה' במאמר זה על זה הדרך **במספר שנים אחר היובל** פירוש כשהוא מוכר במספר השנים למ' או ס' שנה ומעלה, ימכור פירוש יכול למכור וימשך המכר גם אחר היובל ואין היובל מפסיק להוציאה מידו כיון שמכר למספר שנים, ומה שגמר אומר **במספר שני תבואות** וגו' פירוש נותן טעם לדבר למה מכר לשנים ימשך אחר היובל, ואמר במספר שני תבואות ימכר לך מכר זה, פירוש כיון שמוכר לשנים הרי זה אינו מוכר אלא שני תבואות לא גוף הקרקע, שעל מכירתו הוא שמקפיד הכתוב:
@17 **ולא תונו וגו'**. רבותינו ז''ל דרשו (ב''מ נ''ח:) שהכתוב מדבר באונאת דברים, ולפי פשט הכתוב ירצה כי הגם שאמר למעלה אל תונו ודקדק לומר מיד להודיע כי באונאת מטלטלים הכתוב מדבר ולא באונאת קרקע, חש הכתוב שיטעה הטועה כי בקרקעות מותר לאונות, לזה אמר לא תונו וגו', ואמר **ויראת מאלהיך** פירוש הגם שאין דין אונאה בהם, הוא דוקא לענין משפט יושבי תבל, אבל לעולם איסור אונאה יש בדבר, וטעם שאמרתי שאין בו אונאה הוא מטעם שהנחתי משפט זה לדון אותו אני, והוא אומרו **כי אני ה' אלהיכם** פירוש שופט אתכם בדבר הזה לא לצד שמותר לאונות בקרקע, והרבה דינים מצינו בתורה שה' סלק משפטם לבית דין של מעלה, ועיין מה שכתבתי בפרשת משפטים (כ''א י''ב) ומה לפנינו יש טעם בדבר לצד שימצא אדם מוכר שוה מאה בחמשים או להפך אין בית דין יכול לעמוד על הדבר לדעת הקנין שהוא לצד הרצון ואת שהוא לצד האונאה וסלק ה' דינו לבוחן לבות ויודע מחשבות אדם ותחבולותיו:
@17 **וכבר** כתבתי למעלה כי מקח טעות ישנו אפילו בקרקעות, וכן כתב הרמב''ם בפרק ט''ו מהלכות מכירה וכן המוכר לחבירו קרקע וכו' ונמצא במקח מום שלא ידע בו הלוקח מחזירו אפילו לאחר כמה שנים ע''כ, ופירושנו זה כללוהו חז''ל במאמרם שאמרו אל תונו באונאת דברים שבזה נכלל כל מין אונאה כי גם המאנה חברו לרמותו בדברי שקר הוא מאנהו והרי הוא בכלל אונאת דברים:
@19 **ונתנה הארץ פריה**. פירוש פרי הקצוב בכחה לעשות, שהגם שנראה פרי הארץ לא נשער כי זה הוא כח הארץ ולא יותר, שהלא תמצא (כתובות קי''ב.) שגער החכם בארץ ועצרה כחה ולא נתנה פירותיה אחר כך כסדר הראשון, והרואה פירותיה אחר גערתו לא קודם יחשוב כי הוא זה כחה:
@19 **ואכלתם לשובע**. אולי כי לצד שאמר ונתנה הארץ פריה שהוא בגבול האחרון בשומן הפירות, וטעם הפירות, לצד זה אין אדם יכול לאכול מהם כדי שביעה, וזה הוא מדברים הנרגשים כפי הטבע, לזה הבטיחם ה' כי יהיו הפירות באופן שיאכלו מהם לשובע:
@19 **וישבתם לבטח וגו'**. והגם שכבר אמר בפסוק שלפני זה וישבתם על הארץ לבטח חזר לומר כן, להבטיח שלא יסובב הפלגת שבח הפירות לבא עליהם שודד, ולזה דקדק לומר בפסוק ראשון וישבתם על הארץ לומר שהבטחה זו היא על חימוד הארץ, והבטחה שניה על חימוד פירותיה, ובזה נמצאו בטוחים על הארץ ועל פירותיה:
@20 **וכי תאמרו וגו'**. פשט הכתוב הוא על זה הדרך וכי תאמרו מה נאכל, ולצד שיש במשמעות מאמר זה ב' דרכים, הא' הוא טעם שלילות הרצון בדבר זה שלא יזרעו וכו' שאם כן מה נאכל ובהכרח לזרוע לחיותנו על האדמה, ודרך ב' הוא שאלה על הנסבב מקיום מצוה זו מה נאכל כיון שלא נזרע, לזה בא הכתוב ופירש הכוונה במאמר מה נאכל במה שגמר אומר **הן לא נזרע** וגו' פירוש לא שאנו אומרים מה נאכל לתת טעם לשלילות קיום מצוה זו אלא הן אנו מקבלים לא נזרע וגו' אלא כבן שאומר לפני אביו מה נאכל אז וצויתי וגו', אבל אם תהיה כוונתם במאמר מה נאכל לדרך הראשון אז לא יצו ה' אתם את הברכה:
@21 **וצויתי את ברכתי וגו'**. ברכה זו אינה בצומח שכבר הבטיח ונתנה הארץ פריה שהוא גבול שגבל ה' בכחה, אלא שמבטיח ברכת התבואה ככד קמח הצרפית (מלכים א' י''ז) וכשמן אשת עובדיה (מ''ב ד'), והוא שדקדק לומר **ועשת את התבואה** פירוש הברכה שיצו ה' תעשה ריבוי בתבואה כדי שתספיק לג' שנים הגם שהארץ תוציא צמחה כמדי שנה בשנה, צא ולמד מקב חטים שבעליה (תענית כ''ד.), ועיין מה שפירשתי בפסוק וכי יש לי כל (בראשית ל''ג י''א):
@21 **לשלש השנים**. פשט הכתוב הוא לשנה עצמה שהיא ששית ושנת שביעית ושנה שמינית, על זה הדרך מחודש סיון של שנה ו' עד חודש סיון של ז' ושל ח' הרי ב' שנים ומחודש סיון של ח' עד סיון של תשיעית הרי ג' שנים, והוא מאמר הכתוב **עד השנה התשיעית** ולא עד תחלתה של ט' אלא עד בא תבואתה הרי ג' שנים מיום ליום, והוצרך הכתוב לפרש לבל תחשוב שמקצת שנה חשוב שנה:
@22 **וזרעתם את השנה וגו'**. הוצרך לומר כן, מצד שאמר ועשת את התבואה לג' שנים חש שיאמר האומר אם שנה שמינית בת זריעה היא למה יעשה נס כדי שתהיה תבואת שנה ו' עושה לשמינית, לזה גמר אומר וזרעתם את השנה השמינית, ונתן טעם לברכת תבואת שנה ו' צורכי שנה שמינית שהוא מטעם ואכלתם מן התבואה ישן כדי שתאכלו שנה שמינית תבואה ישן ולא חדש כי הישן משובח לבריות יותר מן החדש (ב''ב צ''א:) כידוע, וכרחם אב על בנים ירחם ה' על עמו:
@25 **כי ימוך אחיך וגו'**. פרשה זו תרמוז ענין גדול והערה ליושבי תבל, כי ימוך על דרך אומרו (קהלת י' י''ח) בעצלתים ימך המקרה, ואמרו ז''ל (תענית ז':) עשיתם לאותו שנאמר בו (תהלים ק''ד) המקרה במים עליותיו מך, כי כשהתחתונים מטין מדרך הטוב מסתלקים ההשפעות ומתמסכן עמוד הקדושה, כי העיקר תלוי בהתחתונים, ואמר **ומכר מאחוזתו** ירצה על המשכן משכן העדות אשר הוא אחוזתו ית' שבו השרה שכינתו ובעונותינו נמכר הבית ביד האומות, וכמאמרם ז''ל (מדרש תהלים ע''ט) בפירוש פסוק מזמור לאסף באו גוים וגו', והודיע הכתוב כי גאולתו היא ביד הצדיק אשר יהיה קרוב לה' על דרך אומרו (לעיל י' ג') בקרובי אקדש הוא יגאל ממכר אחיו, כי האדון ב''ה יקרא לצדיקים אח כביכול דכתיב (תהלים קכ''ב) למען אחי ורעי, והגאולה תהיה בהעיר לבות בני אדם ויאמר להם הטוב לכם כי תשבו חוץ גולים מעל שלחן אביכם ומה יערב לכם החיים בעולם זולת החברה העליונה אשר הייתם סמוכים סביב לשלחן אביכם הוא אלהי עולם ב''ה לעד, וימאיס בעיניו תאוות הנדמים ויעירם בחשק הרוחני גם נרגש לבעל נפש כל חי עד אשר יטיבו מעשיהם, ובזה יגאל ה' ממכרו, ועל זה עתידין ליתן את הדין כל אדוני הארץ גדולי ישראל ומהם יבקש ה' עלבון הבית העלוב:
@26 ואומרו **ואיש כי לא יהיה לו גואל**. על דרך אומרם ז''ל (סנהדרין צ''ג.) אין איש אלא הקדוש ברוך הוא דכתיב (שמות ט''ו ג') ה' איש מלחמה, כשלא יהיה לו גואל כי אין איש שם על לב אין מנהל ואין מחזיק ביד אומה ישראלית להשיבה אל אביה, אל תאמר כי ח''ו אבדה תקוה, אלא והשיגה ידו ומצא כדי גאולתו, אמרו ז''ל (סנהדרין צ''ח) כי היסורין והגלות הם תקון האומה להכשירה, והוא מה שרמז **והשיגה ידו** על דרך אומרו (דברים ב' ט''ו) יד ה' היתה בם שהיא מדת הגבורה החובטת באומה בגלות המר, ובאמצעות זה ישיג למצוא כדי גאולת הבית:
@27 ואומרו **וחשב וגו'**. הנה לצד שהמכר הוא בעונותינו כאומרו (ישעי' נ' א') הן בעונותיכם נמכרתם והעון הוא חוב על האדם, בשעת קריעת השטר צריך לעשות חשבון החוב שעליו ולפרוע הנשאר, והוא אומרו **וחשב את שני ממכרו** השנים שנשאר הבית מכור ויתנכה לפי שיעור השנים מעונות ישראל, והעודף ישיב על דרך אומרם ז''ל (יומא פ''ו:) במשפטי התשובה ותיקוניה תשובת המשקל אם אדם נהנה מהעון יסגף עמו כשיעור מה שנהנה מהחטא ובזה יפרע חובו, וכמו כן יעשה אדון העולם כשיתקרב זמן הגאולה, והוא מאמרם ז''ל (סנהדרין צ''ח) שיהיו חבלי משיח, ובזה **ושב לאחוזתו** פירוש חוזר אל הקדוש ברוך הוא, גם על ישראל על דרך אומרו (דברים ל' ג') ושב ה' את שבותך ואמרו ז''ל (מגילה כ''ט.) ישיב לא נאמר אלא ושב וגו':
@28 **ואומרו ואם לא מצאה ידו די השיב**. פירוש אם יראה האדון כי אין כח בעם לסבול חבלים עוד ורבו חובותיהם למעלה ראש ואפם בהם כח הסבל, **והיה ממכרו עד שנת היובל** שהוא זמן המוגבל לגאולה בעתה, ואז **ויצא ביובל ושב לאחוזתו** כי קץ הגלות ישנו אפילו יהיו ישראל רשעים גמורים ח''ו:
@29 **ואיש כי ימכור**. אחר שאמר ענין מכר הבית חזר הכתוב לתת טעם לדבר איך יהיה הדבר הזה שימכור ה' אחוזתו בית הבחירה, והוא אומרו ואיש זה הקדוש ברוך הוא, **כי ימכור בית מושב** פירוש בית שבו מושב אלהים זה בית המקדש, עיר חומה זו ירושלים דכתיב (תהלים קכ''ה) ירושלים הרים סביב לה, אמר הטעם הוא **והיתה גאולתו** שבאמצעות זה אדרבה נגאל, על דרך אומרם ז''ל (מדרש תהלים ע''ט) בפסוק מזמור לאסף וגו' שהשליך ה' חמתו על עצים ואבנים שזולת זה לא היה נשאר מישראל שריד ופליט ואם אין ישראל אין בית המקדש ולא ירושלים, לזה והיתה גאולתו של עם וגאולת הבית כי יש תקוה ושבו בנים לגבולם:
@35 **וכי ימוך אחיך וגו'**. פרשה זו תעיר האדם על רוח ה' אחינו אשר שכן בתוכנו, ואמר כי ימוך אחיך שהוא רוח החיים אשר נטע בתוכנו לחיותנו, אם ראה האדם כי לא האיר בתורה ולא במצות כי אין עני כי אם מן התורה והמצות, **ומטה ידו** והחשיך אורו והודו, **עמך** פירוש לצד היותו עמך הוא שנתמוטט שזולתך היה אורו מאיר מסוף העולם ועד סופו, ותמצא שיבקש ה' להחזיר לו הרוח כאשר נתנה כאומרו (קהלת י''ב ז') והרוח תשוב וגו' ואמרו ז''ל (שבת קנ''ב:) תנה לו כמן שנתנה לך, ויצו ה' **והחזקת בו** פירוש שיתחזק לשוב בתשובה להשיבו למכונו, כי אין לך דבר המעמיד לרוח החיוני במקום גבוה כתשובה:
@35 **ואמר גר ותושב**. דע כי אמרו יודעי נסתרות לה' (קב הישר פל''ב) כי יש בחינת נפשות שה' מביאם באדם בסוד העיבור לסיבות ידועות, יש שבאים להתגורר עם האדם בעשותו איזה מצוה כדי להשתתף במעשה וזוכה בזה, ויש שבאה ומתישבת לסיבות מופלאות אשר הפליא ה' בתיקון הנפשות, וכנגד שניהם אמר **גר ותושב וחי עמך** כנגד ב' הנפשות הבאים שלא מדעתו כשהוא מתחזק לשוב בתשובה, ויזהר עוד שלא יחשיך אור רוחו והגרים אתו, והוא אומרו **אל תקח מאתו** מת שיש בו ובמה בנשך ובמרבית כאשר אבאר בסמוך, **ויראת מאלהיך** פירוש כי מאורו חלק הנפשות הטהורות השיב לו פקדונו, ומבקש עוד **וחי אחיך עמך** שיחזיר הנפש בתוספות חיות באמצעות עבודת הקודש אשר ציוהו ה', והגם שאמרו תנה לו כמו שנתנה לך, זה צד ההסתפקות, או לפי מה שפירשתי בספרי חפץ ה' (שבת קנ''ב) כי כשיתנה לה' כמו שנתנה לו בזה היא מתעלית ומוסיפה חיים ואור עליון ועיין שם:
@37 ואמר **את כספך וגו'**. כאן פירש מה הוא הנשך והתרבית אשר מחשיכים אורו, **את כספך** הם הדברים שהאדם כוסף בעולם הזה לדברים הנדמים, **לא תתן לו בנשך** כי כשאדם משלים תאות נפשו הבהמית ומטעים רוחו מכסופיו הוא נשוך בזה ומטיל בו ארס החטא, ואמר **ובמרבית לא תתן אכלך** פירוש אפילו אכלך שהוא דבר שהורשית לאכול לא תרבה בו, כי כשאדם הולך אחר גרונו ויטה גבול התאוה שבו למותרות בזה יחשיך אור הנפש כי כשזה קם זה נופל כשמתרבה תאבון המורגש מתמעט תאבון הרוחני, והוא מאמר הכתוב (משלי י''ג כ''ה) צדיק אוכל לשובע נפשו, לא להנאת ההרגש, ואומרו **אני ה'** וגו' פירוש והגם שאני אומר לכם להוציא אתכם מארץ מצרים לתת לכם את ארץ כנען לא לאכול מטובה ולשבוע מפריה הוא התכלית אלא להיות לכם לאלהים הוא עיקר הארץ, ואמרו ז''ל בתורת כהנים וז''ל כל היושב בארץ ישראל מקבל עליו עול מלכות שמים:
@39 **וכי ימוך אחיך וגו'**. פרשה זו תרמוז למה שאמרו ז''ל בספר הזוהר (תיקונים י') כי ה' צוה לשר אדום שהוא ס''מ שלא יתנהג באכזריות עם ישראל, והוא אומרו **כי ימוך אחיך** על דרך אומרו (מלאכי א') הלא אח עשו ליעקב, עמך פירוש נמיכותו ועניותו הוא לצד היותו עמך שנתלוה לדרכיך הרעים, **ונמכר לך** על דרך (ישעי' נ''ב ג') חנם נמכרתם ודרשו בספר הזוהר (ח''ב קכ''ח.) כי בחינת ס''מ תקרא חנם, שגלות החל הזה הוא לאדום זכור ה' לבני אדום, ויצו ה' **לא תעבוד בו עבודת עבד** על דרך אומרו (ירמי' ב' י''ד) העבד ישראל וגו', אלא **כשכיר כתושב יהיה** וגו', לצד שיש בישראל ב' בחינות, המון העם ויושבי בשבת תחכמוני (ש''ב כ''ג), ותמצא שהגם שישראל מעלין מסים וארנוניות אין לומדי התורה בכלל דכתיב (דברים ל''ג ג') והם תוכו לרגליך ואמרו ז''ל (ב''ב ח'.) וכו', וכתיב (עזרא ז') מנדה בלו והלך לא שליט וגו', כנגד ההמון עם אמר כשכיר שהם מכורים בעד עונותיהם, וכנגד הצדיקים אמר כתושב שאינם אלא יושבים בין האומות בגלות אבל אין עליהם משא מלך:
@39 **ואומרו** עד שנת היובל הוא גבול הגאולה כידוע יעבוד עמך, ומודיע ה' כי סוף סוף יצא מעמו דכתיב **ויצא מעמך**, **הוא ובניו** פירוש הניצוצים המתבררים באמצעות היותם עמו והוא סוד הגלות, שאם לא כן למה לא ייסרם ה' בשבט מוסר שם בארצם ובנחלתם אלא אחד מהטעמים הוא כדי שיבררו הניצוצות של הקדושה מבין הארצות כי כל מקום ומקום שימצאון שם ישראל באמצעות היסורין והתורה והמצות הניצוצות מתבררים מעצמם, והוא סוד אומרו (קהלת ח') עת אשר שלטה האדם באדם לרע לו. ואם תאמר אם כן אם לא היו ישראל חוטאים וגולים מי היה מברר המתבררים עתה בתפוצת ישראל, דע כי אם לא היו ישראל חוטאים היה להם כח לברר ניצוצות הקדושות במקום שהם מכל המקומות אשר באו שם, מה שאין כן אחר חטאם דחלש כחם ולואי שתשיג ידם במקום עצמו אשר שם הניצוצות, ואמר **ושב אל משפחתו** כי בבא הגואל יטע ה' בתוכנו אורו יתברך אשר שם הוא משפחת עם בני ישראל, גם יקומו שוכני עפר וישובו כל אחד אל אחוזת אבותיו הוא אור עולם בית המקדש כוננו ידיו יתברך לא תרדה בו בפרך ויראת מאלהיך, ומצד דבר זה יתחייב מיתה ס''מ לעתיד לבא כמאמרם ז''ל (סוכה נ''ב.) שהרי הוא מותרה ועבר מצות ה':
@55 **כי לי בני ישראל עבדים וגו'**. צל''ד למה כפל לומר עבדים עבדי הם, ונראה כי יכוין לומר על זה הדרך כי לי בני ישראל עבדים מעיקרם קדושים מבטן ומהריון בשורש נפשותם הגם שלא היה מוציאם ממצרים, וכל זה למה שממנו ואליו, אבל מה שמהם לחייבם להחזיק את עצמן לעבדים עבדי הם אשר הוצאתי אותם מארץ מצרים שהוא טעם מוכרת להם ומחייב להתייחס להם שם עבדות:
@55 **אני ה' אלהיכם**. טעם שהתחיל הכתוב לדבר דרך נסתר כי לי וגו' עבדי הם וגמר אומר לנוכח אני ה' אלהיכם, אולי כי לצד שמצוה לקונה עבד עברי שישלחנו בשנת היובל, לזה נתן לו הטעם לצד שהוא עבד ה' כאומרו עבדי הם, ולצד שיאמר הקונה כי טעם זה יוצדק לגבי העבד שלא יפקיע עבודתו וימכור עצמו לצמיתות אבל הקונה אין עליו חיוב, ומה גם אם הוא מוכר עצמו לגר תושב או לעקר הוא העובר על מצות ה', לזה גמר אומר **אני ה' אלהיכם** מדבר עם הקונה שעמו התחיל לדבר בתחלת הפרשה כי תקנה ועם אותם שצוה אותם לנוכח לא ירדנו בפרך לעיניך, כי דבר מלך שלטון עליהם לקיים כל הכתוב:
@57 **את שבתותי תשמורו וגו'**. צריך לדעת למה חזר הכתוב וצוה כאן על השבת, ונראה שנתכוין להסמיך מצות שבת למצוה שלפניה דכתיב לא תעשו לכם אלילים וגו' לומר כשם שע''ז שקולה ככל התורה גם מצות שבת שקולה ככל התורה כולה, גם עוד יכוין לומר על השמיטות שהם נקראים שבתות דכתיב (לעיל כ''ה ב') שבת לה' שמזהיר עליהם לשומרם, וסמך לאזהרה זו אומרו **ומקדשי תיראו** על דרך אומרם ז''ל (אבות פ''ה) לא נחרב הבית אלא בשביל שלא שמרו מצות שביעית, וכן אמר הכתוב (לקמן כ''ו ל''ד) אז תרצה הארץ את שבתותיה, והוא עצמו אומרו **את שבתותי תשמרו ומקדשי תיראו** שלא תסבבו להחריבו כשלא תקיימו מצות השבתות, ויש לך לדעת כי הגם שה' משליך חמתו על ביתו ונחלתו לחללה לכפרת עון כאומרם ז''ל (מדרש תהלים ע''ט) בפסוק מזמור לאסף עם כל זה על הכל יביא ה' במשפט כל המסבב בחטאו את הדבר הרע הזה ביום המשפט הנורא כשיעמוד בעל הבית המקודש ויתבע האיש המגרש, ומה גם למה שאמר הנביא (הושע י''א) לא אבא בעיר ודרשו ז''ל (זוהר ח''א א':) נשבע הקדוש ברוך הוא כו' אנה יוליך את חרפתו ומה מענה בלשונו ומה גמול יעריכנו, והוא מה שרמז הכתוכ כאן באומרו ומקדשי תיראו כי עונשו גדול, וישער מזה עונש השמיטה, לשומרה:
@57 **חסלת פרשת בהר סיני**
